detection_rule.starter_template:
rule Elf64_Unstripped_Crackme_License {
    meta:
        description = "Detects unstripped ELF64 binary with cleartext license strings"
    strings:
        $func = "validate_license_key"
        $elf_magic = { 7f 45 4c 46 }
    condition:
        $elf_magic at 0 and $func
}
